?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Manter responsabilidades</title><link rel="stylesheet" href="../assets/vendor/bootstrap/css/bootstrap.min.css?v=2"><link rel="stylesheet" href="../assets/vendor/bootstrap-icons/bootstrap-icons.css?v=2"><link rel="stylesheet" href="../assets/css/app.css?v=1"><?php require_once dirname(__DIR__) . '/components/pagina_padrao.php'; greenPortalEstiloPagina(); ?></head><body class="p-3 bg-light"><main class="container-fluid"><div class="d-flex justify-content-between align-items-start gap-3 mb-3"><div><h4 class="mb-1"><i class="bi bi-pencil-square me-2"></i>Manter responsabilidades</h4><div class="text-muted small">Fornecedor <?= $e($id) ?> — <?= $e($supplier['RAZAOSOCIAL']??'') ?></div></div><a class="btn btn-sm btn-outline-secondary" href="fornecedor_responsabilidades.php?CODFORNECEDOR=<?= $e($id) ?>"><i class="bi bi-eye me-1"></i>Consulta</a></div><?php if($message):?><div class="alert alert-success py-2"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="alert alert-danger py-2"><?= $e($error) ?></div><?php endif;?><?php if(!$permission['pode_editar']&&!$permission['pode_incluir']):?><div class="alert alert-warning">Seu perfil não possui permissão para alterar responsabilidades.</div><?php else:?><form method="post"><input type="hidden" name="action" value="save_rows"><div class="table-responsive border rounded bg-white"><table class="table table-sm align-middle mb-0" id="fornecedorResponsibilityTable"><thead class="table-light"><tr><th>Finalidade</th><th>Destino</th><th>Responsável</th><th>Prioridade</th><th>Principal</th><th>Vigência</th><th></th></tr></thead><tbody><?php foreach($rows as $row):$key=(int)$row['CODATRIBUICAO'];?><tr data-row-key="<?= $key ?>"><td><select class="form-select form-select-sm" name="rows[<?= $key ?>][CODTIPORESPONSABILIDADE]"><?php foreach($types as $type):?><option value="<?= $e($type['CODTIPORESPONSABILIDADE']) ?>"<?= (string)$type['CODIGO']===(string)$row['TIPO_CODIGO']?' selected':'' ?>><?= $e($type['NOME']) ?></option><?php endforeach;?></select></td><td><select class="form-select form-select-sm js-destination" name="rows[<?= $key ?>][TIPO_DESTINO]"><option value="USUARIO"<?= $row['TIPO_DESTINO']==='USUARIO'?' selected':'' ?>>Usuário</option><option value="GRUPO"<?= $row['TIPO_DESTINO']==='GRUPO'?' selected':'' ?>>Grupo</option></select></td><td><select class="form-select form-select-sm js-user" name="rows[<?= $key ?>][CODUSUARIO]"><option value="">Selecione</option><?php foreach($users as $user):?><option value="<?= $e($user['CODUSUARIO']) ?>"<?= (int)$user['CODUSUARIO']===(int)$row['CODUSUARIO']?' selected':'' ?>><?= $e($user['NOME']) ?></option><?php endforeach;?></select><select class="form-select form-select-sm js-group d-none" name="rows[<?= $key ?>][CODGRUPO]"><option value="">Selecione</option><?php foreach($groups as $group):?><option value="<?= $e($group['CODGRUPO']) ?>"<?= (int)$group['CODGRUPO']===(int)$row['CODGRUPO']?' selected':'' ?>><?= $e($group['NOME']) ?></option><?php endforeach;?></select></td><td><input class="form-control form-control-sm" type="number" min="0" name="rows[<?= $key ?>][PRIORIDADE]" value="<?= $e($row['PRIORIDADE']) ?>"></td><td class="text-center"><input type="checkbox" name="rows[<?= $key ?>][PRINCIPAL]" value="1"<?= !empty($row['PRINCIPAL'])?' checked':'' ?>></td><td><div class="d-flex gap-1"><input class="form-control form-control-sm" type="date" name="rows[<?= $key ?>][VALIDO_DE]" value="<?= $e($row['VALIDO_DE']) ?>"><input class="form-control form-control-sm" type="date" name="rows[<?= $key ?>][VALIDO_ATE]" value="<?= $e($row['VALIDO_ATE']) ?>"></div></td><td><button type="button" class="btn btn-sm btn-outline-danger js-delete-row"><i class="bi bi-trash"></i></button></td></tr><?php endforeach;?></tbody></table></div><div class="d-flex justify-content-between mt-3"><button type="button" class="btn 